import React from "react"; //rafce
import "./ClientsList.css";

export const Posts = () => {
  return [
    { title: "Post 1", content: "Contenido del post 1" },
    { title: "Post 2", content: "Contenido del post 2" },
    { title: "Post 3", content: "Contenido del post 3" },
  ];
};

const ClientsList = () => {
  const [list, setList] = React.useState(Posts);
  return (
    <div>
        for
      <div>
        {list.map((post) => (
          <div className="card">
            <h2>{post.title}</h2>
            <p>{post.content}</p>
          </div>
        ))}
        {list.length === 0 && <p>No hay facturas para mostrar</p>}
      </div>
    </div>
  );
};

export default ClientsList;
